DECLARE @length INT = 2;

-- Obfuscation comment
/* Time-based blind SQLi detection script */

-- Obfuscated payload
DECLARE @fragmented_payload1 NVARCHAR(1) = /* Fragmented payload 1 */ SUBSTR(@payload_part1, 1, 1);
DECLARE @fragmented_payload2 NVARCHAR(1) = /* Fragmented payload 2 */ SUBSTR(@payload_part2, 1, 1);

-- Non-blocking payload
SELECT CASE WHEN @fragmented_payload1 = 'a' THEN 1 ELSE 0 END;
SELECT CASE WHEN @fragmented_payload2 = 'a' THEN 1 ELSE 0 END;
